# Ratings: Damage, Control, Debuff, Buff/Heal, Positioning, Utility  (0-5, 6 = exceptional / purple)
# Grades: Spellbook (or Familiar for occult cantrips), Scroll, Wand.  '-' = not applicable.
E = {}
def s(name, r, g, ev):
    E[name] = (r, g, ev)

# ───────────── Cantrips ─────────────
s('Gouging Claw', '500000', 'S--', "Cyrus's default Spellstrike. It's an attack spell, so it uses Aspera's attack roll and 10-foot reach rather than his weaker spell attack. The bleed keeps ticking while he recharges. Swap to Ignition or Needle Darts against bleed-immune constructs, elementals and most undead.")
s('Ignition', '400000', 'A--', "The fire option, with d6s when the target is in Aspera's reach. It earns its keep against trolls, swarms and undead with fire weakness. A Flaming Star spellheart can supply it if a cantrip slot is tight.")
s('Needle Darts', '400001', 'A--', "Piercing damage carrying the properties of whatever metal he holds. Keep a silver piece and a cold-iron piece on him: devils, demons, fey and lycanthropes all care. Its 60-foot range is his best direct cast when nothing is in reach.")
s('Live Wire', '400000', 'B--', "Its failure line still deals the electricity damage, so a Spellstrike that misses (without critically missing) still lands something. It heightens every two ranks, so it falls behind Gouging Claw from about level 7.")
s('Frostbite', '310000', 'B--', "The Fortitude cantrip. The save resolves even when the Strike misses, which makes it the steady choice against high-AC, low-Fortitude targets such as casters and skirmishers. The bludgeoning weakness on a critical failure is for an ally with a hammer.")
s('Electric Arc', '300000', 'B--', "Only one target gets the spell through Spellstrike, so its strength is a direct cast at two enemies from 30 feet. Prepare it on days when Cyrus expects to be kept out of reach.")
s('Void Warp', '201000', 'C--', "A second Fortitude cantrip that only affects the living, so it's dead weight against the undead that Frostbite handles. The enfeebled rider needs a critical failure.")
s('Telekinetic Projectile', '300001', 'C--', "Picks bludgeoning, piercing or slashing from whatever loose object is nearby, which gets past an odd resistance. Needle Darts does the same job with metal properties and more range.")
s('Tangle Vine', '030100', 'B--', "No damage of its own, but through Spellstrike a hit also takes 10 feet off the target's Speed, and a critical hit immobilizes it. Good against a skirmisher that wants to step out of Aspera's reach.")
s('Caustic Blast', '200000', 'C--', "The cheapest Expansive Spellstrike burst at 5 feet, centred on the target's corner. The damage is low and the Reflex save is against Cyrus's DC, so treat it as a swarm or cluster tool, not a main cantrip.")
s('Scatter Scree', '120000', 'C--', "A short line of difficult terrain. With Expansive it covers the squares beside the target, which slows a group trying to reach the back line. Low damage.")
s('Daze', '110000', 'C--', "His only Will cantrip and nonlethal. The stun on a critical failure is rare at magus DC. Keep it for capture jobs.")
s('Shield', '000400', 'A--', "One action, no free hand needed, so it works with Aspera in both hands. Shield Block soaks a large hit, but it competes with Reactive Strike for his reaction. Use it on turns where the third action has nothing better to do.")
s('Detect Magic', '000004', 'B--', "Essential for the party, but the Cleric and Druid can also cast it. Prepare it on investigation days. Magic Sense at level 12 makes it redundant.")
s('Figment', '010003', 'B--', "Create a Diversion with a +2 bonus, or a noise to pull a guard. Cheap scouting and heist help.")
s('Telekinetic Hand', '000003', 'C--', "Retrieve a key, trigger a pressure plate from range, steal an unattended item. Prepare it on dungeon days.")
s('Message', '000003', 'B--', "One-action silent coordination at 120 feet (500 at rank 3). Useful in court scenes and stealth approaches where talking gives the plan away.")
s('Time Sense', '000102', 'C--', "Flavour for Aspera's time theme. The +1 to a precisely timed roll comes up rarely, so leave it to the stave rather than a prepared slot.")

# ───────────── Rank 1 ─────────────
s('Sure Strike', '000600', 'SCC', "The best rank-1 spell a magus can prepare. One action, then the Spellstrike rolls twice and ignores concealment and circumstance penalties. Two rank-1 slots a day keep it ready for the two biggest fights. Pair it with a high-value attack payload or a crit-fishing Strike. The 10-minute immunity limits it to one use per fight, and with one or two fights a day the two rank-1 slots cover it, so a wand adds little.")
s('Thunderstrike', '410000', 'ACD', "A single-target basic Reflex save that heightens by a full die set every rank, so it stays relevant from any slot. The save still resolves when the Strike misses. Metal-armoured foes take a penalty to the save and become clumsy, which feeds Cyrus's Trip.")
s('Fear', '014000', 'ABB', "Frightened 1 even on a success, which lowers the target's AC, saves and checks for the whole party. At rank 3 it hits five targets as a direct cast. Mental and emotion immunity is the main weakness.")
s('Fleet Step', '000050', 'BBC', "+30 feet for a minute. Cast it before a chase or an objective run. It is also one of the Arcane Shroud options. Status bonuses don't stack, so the Laughing Shadow +5 is replaced, not added to.")
s('Tailwind', '000042', 'CCB', "The rank-2 wand gives 8 hours of +10 feet. It's a status bonus, so it overlaps Laughing Shadow's +5 and only adds 5 feet in practice. Still worth the wand if Cyrus fights unarmoured or out of stance.")
s('Grease', '040020', 'BBC', "Cast normally to cover four squares. Anything that falls is prone and off-guard, which turns on Laughing Shadow's extra damage. The object mode can disarm a caster's focus or a weapon on a critical failure.")
s('Befuddle', '003000', 'BCC', "Clumsy 1 even on a success, which lowers AC and the Reflex DC his Trip targets. Stupefied hurts enemy casters. The effect lasts one round, so cast it right before the party acts.")
s('Briny Bolt', '330000', 'SBC', "An attack spell, so through Spellstrike every hit with Aspera also blinds the target until it spends an Interact. That costs the enemy an action or forces flat checks on all its attacks. It heightens by 2d6 per rank. The best debuff payload at rank 1 because it rides weapon accuracy.")
s('Shocking Grasp', '400000', 'ACD', "Legacy option, still available at this table. 2d12 electricity plus 1d12 per rank, delivered with Aspera's attack roll, with a bonus against metal. It pairs with Thunderstrike: this one targets AC, Thunderstrike targets Reflex.")
s('Force Barrage', '200000', 'CCC', "Can't be used with Spellstrike because it has no attack or save. It's a guaranteed finisher on a fleeing target at 120 feet, nothing more.")
s('Breathe Fire', '200000', 'CCD', "A 15-foot cone. With Expansive from reach, the cone starts beside the target and fans away from Cyrus. Scaling is fine but the area is small, and Lightning Bolt replaces it at level 5.")
s('Dizzying Colors', '043000', 'BCC', "A failed save means stunned and blinded, which ends a creature's turn. The incapacitation trait and his DC make it a tool for groups of lower-level foes. Place the cone with Expansive so it fans away from the Champion.")
s('Pummeling Rubble', '200020', 'CCD', "A cone that pushes failures 5 feet away from Cyrus. Rarely better than Acid Grip at rank 2.")
s('Gust of Wind', '030030', 'ACC', "From level 12 this is the cheapest Sprinting Spellstrike there is: a 60-foot line run, no reactions, and every Large or smaller creature in the line that fails goes prone. Prone means off-guard for his Laughing Shadow damage and his allies. Fliers that fail get the critical effect.")
s('Goblin Pox', '003000', 'BCD', "Sickened 1 on a success, delivered through Aspera's reach. Use it against living, non-goblin targets in an attrition fight.")
s('Leaden Steps', '012000', 'BCD', "Encumbered (clumsy 1 and slower) plus electricity weakness that grows with rank. Set it up, then hit with Thunderstrike, Lightning Bolt or Shocking Grasp. Sustaining it costs the action Cyrus wants for recharging.")
s('Command', '030000', 'CCD', "A failure costs the target one action on your terms, such as dropping prone or its weapon. It does nothing on a success, so Fear is usually the better Will spell.")
s('Curse of Slippery Steps', '030010', 'CCD', "One round of difficult terrain even on a success. Use it against a runner or a charger.")
s('Hydraulic Push', '300030', 'BCD', "An attack spell with a 5-foot push on a hit (10 on a crit). Use it to break a grapple, push a foe into a hazard or off a ledge, or into the Champion's reach.")
s('Grim Tendrils', '201000', 'CCD', "A 30-foot Fortitude line. Too narrow and weak once Lightning Bolt arrives.")
s('Horizon Thunder Sphere', '300000', 'BCD', "Two-action version is an attack payload that heightens by 2d6 a rank, close to Shocking Grasp's damage, plus dazzled on a crit. The two-round version is too slow for Cyrus.")
s('Mystic Armor', '000200', 'DDD', "Cyrus wears medium armour. Only worth it if he ever drops armour for the unarmoured Laughing Shadow speed bonus.")
s('Jump', '000030', 'CCC', "One action, 30-foot jump without touching the ground. Useful on vertical maps before Time Jump or Fly. At rank 3 it lasts a minute on one creature.")
s('Gentle Landing', '000003', 'BBD', "A reaction, so it only works if it's prepared or a scroll is already in hand. Keep one prepared on cliffside, airship or tower days.")
s('Interposing Earth', '000300', 'CCD', "Reaction cover against one Strike or area. Competes with Reactive Strike, which usually does more.")
s('Illusory Object', '020004', 'BAC', "A fake wall, door or crate. Its rank-2 version adds sound and touch for an hour. Few spells solve as many different problems.")
s('Illusory Disguise', '000004', 'CAC', "Planned infiltration. Rank 3 copies a specific person, rank 4 disguises ten people. Better from a scroll because Cyrus can't predict the day he needs it.")
s('Helpful Steps', '000023', 'CAC', "Legacy. A 40-foot staircase for the whole party. Cheaper than Fly for getting four people up a wall.")
s('Runic Weapon', '000300', 'CDD', "Aspera already has its runes. Only useful for a backup weapon.")
s('Conductive Weapon', '200200', 'CCD', "+1 shock for a minute, d12 against metal. Cast it before a fight against armoured soldiers if Aspera has an empty property slot.")
s('Friendfetch', '000040', 'CBD', "Legacy. Pulls one or two allies straight to Cyrus. Gets a downed or grabbed ally out of a lane without spending the Cleric's turn.")
s('Pocket Library', '000003', 'CCB', "A rank-1 wand gives a daily +1 Recall Knowledge for his Arcana or Lores. Heightened from a slot it lasts multiple uses. It takes three actions to cast, so cast it during exploration.")

# ───────────── Rank 2 ─────────────
s('Acid Grip', '332050', 'SBC', "Moves the target even on a success, so the payload always does something. Pull a foe off the Cleric, into the Champion's reach, or out of a corridor. The persistent acid also takes 10 feet off its Speed. Good at 120 feet as a direct cast.")
s('Invisibility', '000436', 'SAA', "Only Cyrus brings this to the party. Rank 2 is the scouting and extraction version and makes a strong wand. Rank 4 lasts through hostile actions, so Cyrus attacks from undetected and the target is off-guard.")
s('Blazing Bolt', '400000', 'ACD', "The two-action version delivers 4d6 fire on Aspera's attack roll and heightens by 2d6 a rank. A high-slot attack payload that doesn't depend on DC.")
s('Telekinetic Maneuver', '040040', 'ACD', "Through Spellstrike the Strike result decides the Trip, Shove, Reposition or Disarm. Cyrus damages and trips the target in one activity without spending a separate Athletics action or raising his MAP further. It doesn't heighten, so it stays a rank-2 slot.")
s('Sudden Bolt', '400000', 'BCD', "Legacy. 4d12 basic Reflex that heightens by 1d12 a rank, the biggest single-target save damage at rank 2. The save resolves even on a missed Strike.")
s('Acid Arrow', '300000', 'CCD', "Legacy. Heightens only every two ranks. Blazing Bolt does more.")
s('Disintegrating Puddle', '320000', 'BCD', "An attack payload that also leaves an acid puddle around the target for a minute. Good when enemies have to come through that square.")
s('Laughing Fit', '042000', 'BCD', "Stops the target's reactions even on a success, and a failure also slows it. Use it before the party moves past a creature with Reactive Strike. Sustaining it each turn competes with recharging.")
s('Stupefy', '003000', 'CCD', "A caster lock with a short success effect. Befuddle and Improvise Strategy cover the same job.")
s('Revealing Light', '003004', 'BAC', "Makes invisible creatures concealed and strips other concealment, so the whole party can target them. A 10-foot burst works with Expansive.")
s('Noise Blast', '300000', 'BCD', "A Fortitude burst for Expansive Spellstrike. A critical failure stuns. Use it when the cluster has weak Fortitude and strong Reflex.")
s('Dimensional Drop', '230000', 'BCD', "Falling damage and the target lands prone, which makes it off-guard. A Reflex payload for grounded foes.")
s('Dispel Magic', '020005', 'BAD', "Counteracts a buff, a ward or a hostile effect. The Cleric and Druid share it. A scroll is fixed at its rank, so buy the rank that can counteract what you're facing.")
s('See the Unseen', '000004', 'BBA', "Shows invisible creatures as concealed and lets Cyrus see incorporeal creatures through walls. A rank-5 wand lasts 8 hours, which covers a whole dungeon.")
s('Blur', '000400', 'ABB', "Studious from level 7. Casting it lets Cyrus enter Arcane Cascade as a free action, so he starts the fight concealed and in stance for two actions.")
s('Mirror Image', '000400', 'BBC', "Legacy. Three images that soak hits from multiple weapon attacks. Best against a brute with many Strikes.")
s('Resist Energy', '000400', 'BAB', "Resistance 5 that rises to 10 for two people at rank 4. Cast it before the dragon fight.")
s('Loose Time\'s Arrow', '000340', 'BBB', "Quickens up to six creatures for an extra Step or Stride. A strong opener when the party needs to close or cross a map.")
s('Enlarge', '000430', 'BBC', "On the Champion: more reach and damage. On Cyrus: Large, 15-foot reach with Aspera and +2 damage, at the cost of clumsy 1 and a bigger footprint for flanking and teleport landing.")
s('Gecko Grip', '000032', 'ACC', "Studious from level 7, so it's already in the spellbook and gives a free Arcane Cascade. Climb Speed equal to Speed lets Cyrus fight from walls.")
s('Water Breathing', '000003', 'CAD', "Five people breathe underwater for an hour. Buy a scroll when the adventure points at water.")
s('Blood Vendetta', '220000', 'CCD', "A reaction that needs Cyrus to take piercing or slashing damage first. Reactive Strike is usually the better use of the reaction.")
s('Embed Message', '000002', 'CCD', "Dead drops and coded warnings. A roleplay tool that rarely needs a slot.")

# ───────────── Rank 3 ─────────────
s('Haste', '000650', 'SAA', "The Druid can cast it too (it's also primal), so agree who prepares it. On himself, the extra Stride or Strike lets him close and Spellstrike every turn. On the Champion it's an extra Strike every round. Studious from level 11, which also gives free Arcane Cascade. With one or two fights a day, a rank-3 wand is close to a free Haste every fight.")
s('Slow', '050400', 'SAB', "Slowed 1 even on a success, for a round. A failure lasts a minute. Delivered on a Strike, it costs a boss a third of its turns. The Druid can also cast it. At rank 6 it hits ten targets as a direct cast.")
s('Time Jump', '000060', 'ABC', "One action for two moves that nothing can react to, then Spellstrike in the same turn. Reach a back-line caster or escape a surround. Using it twice in a minute leaves Cyrus stupefied 4.")
s('Lightning Bolt', '400000', 'SBD', "The main line spell. Expansive lets the 120-foot line start beside the target, so it rarely catches allies. From level 12, Sprinting Spellstrike turns it into a long-distance charge through enemies that provokes no reactions.")
s('Fireball', '400000', 'BBD', "Excellent cast normally at 500 feet. Through Expansive the 20-foot burst usually includes Cyrus at 10-foot reach. The Druid can cast it too.")
s('Cave Fangs', '430000', 'BBD', "Piercing damage and a minute of difficult terrain. Physical damage gets past elemental resistance. The burst has the same self-hit problem as Fireball.")
s('Blindness', '005000', 'BCD', "Blinded for a minute on a failure. A success only lasts until the target's turn begins, and incapacitation makes it unreliable against bosses. Fortitude target.")
s('Paralyze', '050000', 'BCD', "Stunned 1 on a success, paralyzed on a failure. Incapacitation limits it to lower-level foes.")
s('Blister Bomb', '004000', 'ACD', "Sickened 2 on a success. That's −2 to AC, saves and attacks for every creature in a small burst. The 5-foot burst is easy to place with Expansive. Doesn't work on creatures immune to disease.")
s('Earthbind', '030000', 'CBD', "Grounds a flier. Buy a scroll when the adventure involves wyverns or harpies.")
s('Magnetic Acceleration', '400000', 'BCD', "6d6 on Aspera's attack roll, +2d6 a rank, with a bonus against metal. Pick this or Blazing Bolt.")
s('Wooden Double', '000400', 'BCD', "A reaction that turns a critical hit into a hit on a wooden decoy. Worth preparing against brutes with big crits.")
s('Ghostly Weapon', '000302', 'ABD', "Studious from level 11. Until then a scroll gives Aspera ghost touch for five minutes when the party meets incorporeal undead.")

# ───────────── Rank 4 ─────────────
s('Fly', '000365', 'AAB', "Studious from level 13. Flight for five minutes on Cyrus or an ally. The Druid and Cleric can also cast it, so agree who prepares it.")
s('Translocate', '000054', 'AAB', "Studious from level 13. A 120-foot teleport that escapes grapples and walls. Rank 5 reaches a mile. Dimensional Assault already covers short hops.")
s('Vision of Death', '403000', 'BCD', "Frightened 1 even on a success, plus mental damage. Use it against living targets with weak Will.")
s('Containment', '050300', 'BBD', "Locks one creature in a force field, or protects a downed ally. Remember the field blocks allies' attacks too.")
s('Force Rain', '400000', 'BCD', "The two-action version is a 10-foot force burst for Expansive. Force has few resistances.")
s('Life-Draining Roots', '300200', 'CCD', "A 30-foot line with temporary HP. Lightning Bolt from a higher slot usually does more.")
s('Grasping Earth', '040000', 'BCD', "Grabbed targets are off-guard, which turns on Laughing Shadow damage. The burst works with Expansive. The damage only comes from sustaining.")
s('Confusion', '040000', 'BCD', "Stunned 1 on a success. A failure confuses the target for up to a minute, saving at the end of each of its turns.")
s('Unfettered Movement', '000330', 'CBC', "Auto-Escape grapples for 10 minutes. Cast it on the ally a grappler targets.")
s('Clairvoyance', '000004', 'CAB', "An invisible scouting eye that doesn't need line of sight. A one-minute cast during exploration.")
s('Wall of Mirrors', '040002', 'BBD', "A two-action wall that conceals everything across it. The printed text gives no duration, so get a ruling before relying on it.")

# ───────────── Rank 5 ─────────────
s('Weight of the World', '354000', 'SBD', "Stunned 1 even on a success, plus dazzled. On a failure, stunned 2 takes two actions from a boss. Best Fortitude payload at rank 5.")
s('Wall of Stone', '060043', 'SAC', "Three actions to split a fight in half, block a reinforcement lane or build a bridge. The best control spell Cyrus can cast at this rank.")
s('Glacial Skewer', '530040', 'ACD', "Big cold damage on Aspera's attack roll, and the push slams the target into a wall to immobilize it. Line up the wall first.")
s('Blazing Fissure', '432000', 'ACD', "A 120-foot line where every failed save means prone. With Sprinting Spellstrike, Cyrus runs the line and everyone he passes is on the floor and off-guard when he arrives.")
s('Tornadic Gale', '430040', 'ACD', "Pulls Medium or smaller creatures adjacent to the line into it before the damage. With Sprinting, the line follows his path, so it catches a whole flank.")
s('Howling Blizzard', '420000', 'BCD', "The two-action 60-foot cone is the Expansive version. The three-action burst can't go through Spellstrike.")
s('Impaling Spike', '340000', 'BCD', "Immobilized on a failure, off-guard on a critical failure. It's cold iron, which matters against fey and demons.")
s('Shadow Siphon', '000400', 'CCD', "Legacy. A reaction that halves a damaging spell's damage for everyone. Useful against enemy blasters, but it competes with Reactive Strike.")
s('Corrosive Muck', '340000', 'BCD', "Two pools of greater difficult terrain that hurt anything entering. Cast normally to lock down approach lanes.")
s('Banishment', '050000', 'CCD', "Sends a fiend home. In the Forgotten Realms that means devils and demons. Incapacitation limits it.")
s('Space Fold Gate', '000054', 'CBD', "Three actions to link two squares 200 feet apart. Moves the whole party, but enemies can use it too.")
s('Magic Passage', '000004', 'CAD', "A tunnel through 10 feet of stone or wood. Metal blocks it. Buy a scroll for a raid on a fortified site.")
s('Scouting Eye', '000004', 'CBC', "A mobile invisible eye. Better than Clairvoyance when there's a route to follow.")
s('Sending', '000004', 'CAC', "A 25-word message anywhere on the planet, with a reply.")

# ───────────── Rank 6 ─────────────
s('Disintegrate', '600000', 'SBD', "12d10 untyped damage on Aspera's attack roll, and a critical hit worsens the Fortitude save by a degree. With Sure Strike first, it's the hardest-hitting payload he'll have for several levels. It also deletes walls of force.")
s('Chain Lightning', '400000', 'BCD', "Spellstrike reduces it to one target, so cast it normally. The chain ends if any target critically succeeds, which happens often at magus DC.")
s('Living Thunderbolt', '300350', 'BCD', "A 60-foot fly Speed and damage to anything Cyrus passes through. It's a polymorph, so check with Alex how it interacts with wielding Aspera.")
s('Wall of Force', '050000', 'ABD', "An invisible, nearly unbreakable wall for a minute. Splits the fight hard.")
s('Silver Spear', '500000', 'ACD', "12d6 piercing on Aspera's attack roll, with 12d6 extra against fiends and a teleport lock on a crit. It's silver, which matters against devils.")
s('Petrify', '040000', 'BCD', "Slowed 1 even on a success. A failure risks permanent petrification over a few turns.")
s('Cast into Time', '330000', 'CCD', "Removes everyone in the cone until the end of Cyrus's turn, so he can't follow up on them. Mostly damage.")
s('Unexpected Transposition', '000430', 'BCD', "A reaction that swaps Cyrus with another creature so the attack hits them instead. Swap with an enemy for the best effect.")
s('Collective Transposition', '020050', 'BBD', "Teleports two or more creatures within 30 feet. Pull allies into a flank, or throw an enemy away from a downed ally.")
s('Truesight', '000005', 'CAC', "Sees through illusions and shapechangers for 10 minutes. Buy a scroll for an infiltration.")
s('Mislead', '000433', 'BBD', "Invisibility plus a decoy that acts for Cyrus. Sustaining it costs an action each turn.")
s('Teleport', '000005', 'CAC', "Ten minutes to move the party up to 100 miles. An expedition tool.")

# ───────────── Rank 7 ─────────────
s('True Target', '000600', 'SBC', "One action: Cyrus and three allies roll twice on their first attack against the target and ignore concealment. Cast it, then Spellstrike in the same turn. Best when the Champion and other attackers act before the target.")
s('Frigid Flurry', '500050', 'SCD', "Only hurts foes, then carries Cyrus to the far end of the line, immune to most effects while he travels. With Sprinting, ask Alex how the spell's carry and the feat's Stride combine.")
s('Beheading Buzz Saw', '400000', 'BCD', "A 60-foot line with heavy persistent bleed. A success means no damage at all, which is a real risk at magus DC.")
s('Eclipse Burst', '400000', 'CCD', "A 60-foot burst. Cast it normally from far away. Too big for Expansive.")
s('Telekinetic Bombardment', '440000', 'ACD', "Prone on a failure and stunned on a critical failure. It can be placed anywhere within 500 feet, including a line that doesn't start at Cyrus.")
s('Comet Charge', '500050', 'ACD', "A 120-foot charge that triggers no reactions, then a melee spell attack. It's best cast normally, since his spell attack is lower than Aspera's. Through Spellstrike, ask Alex whether the flight happens.")
s('Defy the Gods', '005000', 'BCD', "Drained and stupefied even on a success. Shuts down an enemy caster and wears down a priest.")
s('Spell Riposte', '000403', 'BCD', "Reflects a targeted spell back at its caster. Prepare it for a known caster fight.")
s('Contingency', '000403', 'BBC', "A pre-set reaction spell (Translocate, Fly, Invisibility) that triggers when Cyrus is in trouble. Cast it in the morning.")

# ───────────── Rank 8 ─────────────
s('Arctic Rift', '540000', 'ACD', "A 120-foot Fortitude line for foes with good Reflex. Slowed 1 on a failure, encased in ice on a critical failure.")
s('Disappearance', '000656', 'SAC', "Invisible to every precise sense for 10 minutes, even while attacking. Every Strike Cyrus makes is against an off-guard target.")
s('Quandary', '060000', 'ACD', "No save to resist the initial banishment. The target is gone until it solves the puzzle against Cyrus's DC. Sustaining costs one action a turn, which is cheap for removing a boss.")
s('Roar of Freedom', '403400', 'ACD', "One action: damage to enemies in 30 feet and 15 temporary HP to allies. Fits beside a Spellstrike in the same turn.")
s('Desiccate', '500000', 'BCD', "Hits any number of living creatures at 500 feet. Cast it normally.")
s('Uncontrollable Dance', '054000', 'ACD', "Off-guard and no reactions even on a success, for three rounds. A touch spell, so Spellstrike delivers it at reach. Incapacitation limits it against higher-level foes.")
s('Falling Sky', '050000', 'ACD', "Everything in the cylinder falls prone even on a success, and fliers crash. A failure also stuns. Incapacitation trait.")

# ───────────── Rank 9 ─────────────
s('Foresight', '000603', 'SAC', "An hour of rerolling a priority ally's saves or forcing enemies to reroll attacks against them. Cast it on the Champion before the final fight.")
s('Remake Physiology', '046030', 'SCD', "Clumsy, drained, enfeebled, stupefied, dazzled and −20 feet, even for a round on a success. A touch spell, so Spellstrike delivers it at reach.")
s('Falling Stars', '520000', 'BCD', "Four 40-foot bursts at 500 feet. Cast it normally on an open battlefield.")
s('Phantasmagoria', '440000', 'BCD', "Damages any number of creatures; a success still stops their reactions.")
s('Dimensional Excision', '500000', 'ACD', "Basic Will damage without the mental trait, with a −4 penalty for creatures away from their home plane. Good against extraplanar bosses.")
s('Implosion', '400000', 'BCD', "75 damage to one target, then a new target each time it's sustained. The sustain competes with recharging.")
s('Massacre', '500000', 'BCD', "Kills creatures that fail in a 60-foot line, if they're level 17 or lower. If nothing dies, it backfires on Cyrus.")

# ───────────── Occult only (via Witch or Psychic dedication, level 9) ─────────────
s('Guidance', '000302', 'A--', "A one-action +1 on an ally's roll. The cheapest party support a familiar can carry.")
s('Forbidding Ward', '000300', 'B--', "+1 AC and saves for one ally against one enemy for a minute. Good for protecting a caster from the boss.")
s('Haunting Hymn', '200000', 'C--', "A Fortitude sonic cantrip. Weaker than Frostbite.")
s('Wash Your Luck', '000200', 'C--', "Cancels a misfortune effect once. Narrow.")
s('Know the Way', '000002', 'C--', "Direction finding. Flavour.")
s('Read the Air', '000002', 'B--', "+1 to Make an Impression and a free Society Recall Knowledge. Good for Cyrus's court scenes.")
s('Soothe', '000500', 'FAA', "Ranged healing plus +2 against mental effects. Cyrus becomes the party's backup healer without taking the Cleric's actions. A daily wand covers the emergency.")
s('Bless', '000400', 'FCC', "The Cleric already has it. Only buy it if they don't prepare it.")
s('Bane', '003000', 'FCD', "The Cleric can cast it too. Sustaining it competes with recharging.")
s('Sanctuary', '000300', 'FBC', "Protects a downed ally from follow-up attacks.")
s('Protection', '000300', 'FCB', "+1 AC and saves. Rank 3 covers allies within 10 feet.")
s('Liberating Command', '000300', 'FBB', "One action lets a grabbed ally Escape as a reaction. Cheap rescue.")
s('Ill Omen', '003000', 'FBC', "Forces the next attack roll to be rolled twice and take the worse.")
s('Lose the Path', '030000', 'FCD', "A reaction that turns a charge into difficult terrain.")
s('Phantom Pain', '203000', 'FCD', "Mental damage and sickened. Weak at this rank.")
s('Spirit Link', '000300', 'FCB', "Transfers Cyrus's HP to an ally over time.")
s('Calm', '040000', 'FBD', "Ends hostility in an area. Good for breaking up a brawl that shouldn't be a fight.")
s('Silence', '000004', 'FAC', "Silent movement for one person, or a 10-foot silence aura at rank 4 that also stops casting.")
s('Clear Mind', '000300', 'FAC', "Counteracts frightened and stupefied, and at rank 4 confused, controlled and slowed. A strong emergency scroll.")
s('Cleanse Affliction', '000300', 'FBC', "Reduces or counteracts a curse, disease or poison. The Cleric shares it.")
s('Sure Footing', '000300', 'FBC', "Counteracts clumsy, grabbed or paralyzed, plus more at rank 4.")
s('Paranoia', '030000', 'FCD', "Turns the target against its allies. Hard to control.")
s('Augury', '000003', 'FCD', "A vague yes or no about the next 30 minutes.")
s('Spiritual Armament', '300000', 'FCD', "An attack spell. Striker's Scroll could carry it, but there are better payloads.")
s('Status', '000002', 'FCC', "Tracks an ally's location and condition.")
s('Heroism', '000500', 'FAB', "+1 to attacks, saves, skills and Perception for 10 minutes. The Cleric has it too, but a scroll means it doesn't cost them a slot.")
s('Hypercognition', '000005', 'FAA', "Six Recall Knowledge checks in one action. Huge for a Lore-heavy scholar like Cyrus.")
s('Defensive Prescience', '000200', 'FCD', "Protects a familiar. Only matters if the familiar fights.")
s('Begone', '030030', 'FBC', "One action, push 15 feet on a failure. A one-action Fortitude shove.")
s('Strength of Mind', '000300', 'FCC', "+1 against mental and movement effects.")
s('Focusing Hum', '000002', 'FCD', "Helps stupefied casters. Narrow.")
s('Infectious Melody', '030000', 'FCD', "Makes communication harder. Narrow.")
s('Tortoise and the Hare', '040300', 'FAC', "Slows a foe for a round even on a success. A failure also quickens Cyrus or an ally.")
s('Read Omens', '000003', 'FCD', "A cryptic clue about the coming week.")
s('Honeyed Words', '000003', 'FBC', "+4 to Lie. Good for infiltration if Cyrus is the talker.")
s('Synesthesia', '060000', 'FAB', "Clumsy 3, concealment and a flat check on every concentrate action, even for a round on a success. The goal was to put it on Aspera's stave. Witch or Psychic gives Cyrus the occult Cast a Spell activity, so he can cast it from the staff.")
s('Strange Geometry', '040000', 'FCD', "Areas of illusory terrain. Three actions.")
s('Inevitable Disaster', '400000', 'FBD', "55 basic Fortitude damage, delayed 1d4 rounds. Reliable against a boss.")
s('Death Ward', '000400', 'FBD', "Legacy. Void resistance and +4 to saves against death effects. Buy it for an undead campaign arc.")
s('Shadow Blast', '400000', 'FCD', "Chooses damage type and shape, but the target picks its save.")
s('Zealous Conviction', '000500', 'FAB', "12 temporary HP and Will bonus for up to ten allies for 10 minutes. Cast it before a big fight.")
s('Scintillating Safeguard', '000500', 'FBD', "A reaction that gives five allies resistance 10 against a big area.")
s('Spirit Blast', '400000', 'FCD', "16d6 spirit damage, which hits incorporeal targets.")
s('Blanket of Stars', '000003', 'FCD', "Stealth at night. Narrow.")
s('Ethereal Jaunt', '000044', 'FBD', "Walk through walls for a minute. Infiltration and escape.")
s('Visions of Danger', '420000', 'FCD', "Three actions for a damaging illusion area.")
s('Orb of Twisting Fate', '030000', 'FCD', "Wastes the target's first action. Weak at magus DC.")
s('Spirit Song', '430000', 'FCD', "Spirit damage that reaches incorporeal creatures in walls.")
s('Spiritual Epidemic', '005000', 'FCD', "Permanent enfeebled and stupefied on a failure. Spreads to casters.")
s('Overwhelming Presence', '050000', 'FCD', "Ties up a whole group paying tribute.")
s('Unfathomable Song', '040000', 'FCD', "Sustained random debuffs on up to five targets.")
